```{ojs}
//| echo: false
norm = import('https://unpkg.com/norm-dist@3.1.0/index.js?module')


// Location-shift

mu = math.sqrt(2 * Delta / N)


// Scale-shift

function KL_sigma(s) {
  return N * (s**2 - 1 - 2 * math.log(s)) / 2;
} 

function dKL_sigma(s) {
  return (s - 1 / s) * N;
} 

sigma = newtonRaphson(KL_sigma, dKL_sigma, Delta, 1.1, 1, 100, 1e-5, 100)


// Compute densities
pts2 = 201
dat3 = Array(pts2).fill().map((element, index) => {
  let x = - scale + index * 2 * scale / (pts2 - 1);
  let p = norm.pdf(x);
  let q = norm.pdf(x - mu);
  let r = norm.pdf(x / sigma) / sigma;
  return ({
    x: x,
    p: p,
    q: q,
    r: r
  })
})
```

